// Abort BEFORE burning a partial episode — an episode renders every scene (💸).
// Mirrors MIN_TOKEN_BALANCE=2000 in show/DailyPull/show.env.
// Doubles as the config preflight, so an unfilled Show config fails here in
// seconds — not after the story step.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty — set it to a campaign id the API credential\'s account owns');
if (!cfg.userId) throw new Error('Show config: userId is empty — set it to the YakYak user id the API credential belongs to');
const user = $json;
if (user.tokenBalance === undefined) throw new Error('could not fetch the user record — check Show config userId and the "YakYak API" credential (' + (user.error?.message || 'no tokenBalance in response') + ')');
const balance = Number(user.tokenBalance || 0);
const min = Number(cfg.minTokenBalance || 2000);
if (balance < min) throw new Error('token balance ' + balance + ' is below the ' + min + ' minimum — top up before generating an episode');
return [{ json: { balance } }];

// The date-seeded 3-card draw — port of show/DailyPull/compute.js (same FNV-1a
// + mulberry32 stream, so a given date + exclusion window reproduces the
// showrunner's draw exactly). The 7-draw no-repeat window lives in workflow
// static data — the n8n analog of re-reading the last 7 committed stories'
// audit markers; it is extended in 'Record draw' only after the episode
// rendered. Static data persists only on ACTIVE (scheduled) executions —
// manual test runs draw correctly but don't extend the window.
function h32(s) { let h = 0x811c9dc5; for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 0x01000193); } return h >>> 0; }
function mulberry32(a) { return function () { a |= 0; a = (a + 0x6d2b79f5) | 0; let t = Math.imul(a ^ (a >>> 15), 1 | a); t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t; return ((t ^ (t >>> 14)) >>> 0) / 4294967296; }; }
function shuffle(arr, rng) { const a = arr.slice(); for (let i = a.length - 1; i > 0; i--) { const j = Math.floor(rng() * (i + 1)); const t = a[i]; a[i] = a[j]; a[j] = t; } return a; }

const corpus = String($json.data || '');
const field = (block, name) => { const m = new RegExp('^\\*\\*' + name + ':\\*\\*\\s*(.+)$', 'm').exec(block); return m ? m[1].trim() : ''; };
const cards = corpus.split(/^## /m).slice(1).map((b) => {
  const header = b.slice(0, b.indexOf('\n')).trim(); // "13 — Death"
  const hm = /^(\d+)\s*[—-]\s*(.+)$/.exec(header);
  if (!hm) return null;
  // note: compute.js reuses the key 'reversed' for both the corpus meaning and
  // the drawn orientation (the boolean clobbers the string); kept separate here
  return { number: parseInt(hm[1], 10), name: hm[2].trim(), keywords: field(b, 'Keywords'), upright: field(b, 'Upright'), reversedMeaning: field(b, 'Reversed'), persona: field(b, 'Persona') };
}).filter(Boolean);
if (cards.length < 3) throw new Error('parsed only ' + cards.length + ' cards from the corpus — check Show config corpusUrl');

const now = new Date();
const dateStr = now.toISOString().slice(0, 10); // seed = the UTC date -> daily cadence
const rng = mulberry32(h32('daily-pull:' + dateStr));

const sd = $getWorkflowStaticData('global');
// same-date re-runs drop the day's own record first, so a retry redraws the
// SAME cards instead of excluding them
const recent = (Array.isArray(sd.dailyPullDraws) ? sd.dailyPullDraws : []).filter((x) => x.date !== dateStr).slice(-7);
const excluded = new Set();
for (const r of recent) for (const c of (r.cards || [])) excluded.add(c);
let pool = cards.filter((c) => !excluded.has(c.number));
if (pool.length < 3) pool = cards; // relax rather than fail on a small deck

const POSITIONS = ['Past', 'Present', 'Future'];
const drawn = shuffle(pool, rng).slice(0, 3).map((card, i) => Object.assign({}, card, { position: POSITIONS[i], isReversed: rng() < 0.5 }));
return [{ json: { dateStr, cardNumbers: drawn.map((d) => d.number), excluded: Array.from(excluded).sort((a, b) => a - b), drawn } }];

// Extract the story markdown from the Claude response, then port of
// storyToDescription() from show/showrunner/story-format.js: drop everything
// before the first '## Scene', collapse each scene's prose to one line, append
// `<Char> says: "<dialog>"`, mapping names through the cast map (CAST_ALIASES
// in show/DailyPull/show.env).
const resp = $json;
if (resp.stop_reason === 'refusal') throw new Error('Claude declined the request (stop_reason: refusal)');
const story = (resp.content || []).filter((b) => b.type === 'text').map((b) => b.text).join('\n');
if (!/## Scene/.test(story)) throw new Error('Claude response contains no "## Scene" blocks — not a story');

// ≤50-char social title from the requested '## Social title:' line
let socialTitle = '';
const mTitle = story.match(/^##\s*Social title:\s*(.+)$/mi);
if (mTitle) socialTitle = [...mTitle[1].trim().replace(/^"|"$/g, '')].slice(0, 50).join('');

// caption from the headlines bullets
const capLines = [];
const hm = story.match(/## Headlines we drew from:\n([\s\S]*?)\n##/);
if (hm) for (const l of hm[1].split('\n')) { const t = l.replace(/^-\s*/, '').trim(); if (t) capLines.push(t); }
const socialCaption = capLines.slice(0, 6).join(' · ').slice(0, 400);

const ALIASES = {"The Reader":"The Reader","The High Priestess":"The High Priestess","The Hierophant":"The Hierophant","The Hanged Man":"The Hanged Man","The Hermit":"The Hermit","The Magician":"The Magician","The Emperor":"The Emperor","The Empress":"The Empress","The Lovers":"The Lovers","The Chariot":"The Chariot","The Fool":"The Fool","The Devil":"The Devil","The Tower":"The Tower","The Star":"The Star","The Moon":"The Moon","The Sun":"The Sun","The World":"The World","Wheel of Fortune":"Wheel of Fortune","Strength":"Strength","Justice":"Justice","Death":"Death","Temperance":"Temperance","Judgement":"Judgement"};
const mapShort = (name) => { for (const k of Object.keys(ALIASES)) if (name.includes(k)) return ALIASES[k]; return String(name).trim(); };

const lines = story.split(/\r?\n/);
let inScene = false, n = 0, prose = '', character = '', dialog = '';
const parts = [];
const emit = () => {
  if (!inScene) return;
  const p = prose.replace(/[ \t]+/g, ' ').trim();
  const s = mapShort(character);
  parts.push(n === 0 ? '- ' + p + ' ' + s + ' says: "' + dialog + '"' : '\n\n  - ' + p + ' ' + s + ' says: "' + dialog + '"');
  n++;
};
for (const line of lines) {
  if (/^## Scene/.test(line)) { emit(); inScene = true; prose = ''; character = ''; dialog = ''; continue; }
  if (!inScene) continue;
  if (/^\*\*Leading character:\*\*/.test(line)) { character = line.replace(/^\*\*Leading character:\*\*[ \t]*/, ''); continue; }
  if (/^\*\*Dialog:\*\*/.test(line)) { dialog = line.replace(/^\*\*Dialog:\*\*[ \t]*/, '').trim().replace(/^"|"$/g, '').replace(/[.。]$/, ''); continue; }
  if (/^##/.test(line)) { emit(); inScene = false; continue; }
  prose += ' ' + line;
}
emit();
if (!parts.length) throw new Error('no scenes parsed from the story');
const plot = parts.join('');
return [{ json: { plot, socialTitle, socialCaption, scenes: n, story } }];

// Shape the engine call: episode mode in the pinned Daily Pull campaign, the
// story as the new episode's plot, optional soundtrack pin. The engine's
// sub-workflow trigger is passthrough — this item IS the payload (same shape
// as the engine webhook's body). Re-delivered same-day stories are diff-aware
// on the engine side, so a duplicate run doesn't re-bill unchanged work.
const cfg = $('Show config').first().json;
if (!cfg.campaignId) throw new Error('Show config: campaignId is empty');
const movie = { plot: $json.plot };
if (cfg.soundtrackAudioPath) {
  movie.soundtrackAudioPath = cfg.soundtrackAudioPath;
  if (cfg.soundtrackVolume) movie.soundtrackVolume = Number(cfg.soundtrackVolume);
}
return [{ json: { target: { mode: 'episode', campaignId: cfg.campaignId }, changes: { movie }, chatWebhookUrl: '' } }];

// Extend the no-repeat window only AFTER the engine returned a rendered
// episode (a failed run re-draws the same cards next time — parity with the
// showrunner, whose window reads committed story files). Same-date re-runs
// replace the day's entry instead of double-counting it. Only active
// executions persist static data.
const sd = $getWorkflowStaticData('global');
const d = $('Draw cards').first().json;
const arr = (Array.isArray(sd.dailyPullDraws) ? sd.dailyPullDraws : []).filter((x) => x.date !== d.dateStr);
arr.push({ date: d.dateStr, cards: d.cardNumbers });
sd.dailyPullDraws = arr.slice(-7);
return $input.all();
